  'chat.workStatus.telemetry.cacheHit': 'Кэш',
  'chat.workStatus.telemetry.cacheHitDescription': 'Доля входных токенов, повторно использованных из кэша промпта на всех шагах. Повторное использование контекста может снизить стоимость и ожидание, но это не показатель скорости.',
  'chat.workStatus.telemetry.cost': 'Стоимость',
